declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_permission('customers.create');$data=['name'=>'','phone'=>'','email'=>'','address'=>'','notes'=>'','credit_limit'=>'0.00','status'=>'active'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf();foreach(array_keys($data)as$k)$data[$k]=trim((string)($_POST[$k]??''));if(mb_strlen($data['name'])<2)$errors['name']='Enter a customer name.';if($data['email']!==''&&!filter_var($data['email'],FILTER_VALIDATE_EMAIL))$errors['email']='Enter a valid email.';try{$limit=money_to_cents($data['credit_limit']);if($limit<0)throw new InvalidArgumentException();}catch(Throwable){$errors['credit_limit']='Enter a valid credit limit.';$limit=0;}if(!$errors){$st=db()->prepare('INSERT INTO customers(name,phone,email,address,notes,credit_limit,status,created_by) VALUES(:name,:phone,:email,:address,:notes,:limit,:status,:user)');$st->execute([':name'=>$data['name'],':phone'=>$data['phone']?:null,':email'=>$data['email']?:null,':address'=>$data['address']?:null,':notes'=>$data['notes']?:null,':limit'=>cents_to_decimal($limit),':status'=>$data['status'],':user'=>(int)current_user()['id']]);$id=(int)db()->lastInsertId();audit_log('customer_created','customers',$id,'Customer created: '.$data['name'].'.');flash('success','Customer created.');redirect('customers/view.php?id='.$id);}}
$pageTitle='Add Customer';$pageStyles=['admin.css','commerce.css'];require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/sidebar.php';?>
